botster.register{
  handlers = {{ kind = "mcp_tool", id = "h_t", name = "t", description = "d", input_schema = { type = "object" },
    call = function(payload, request)

      local e = botster.base64.encode{ bytes = "x" }
      local d = botster.base64.decode{ text = e.value }
      local j = botster.json.encode{ value = { a = 1 } }
      local jd = botster.json.decode{ text = j.value }
      local i = botster.ids.new{}
      local now = botster.clock.now{}
      local mono = botster.clock.monotonic{}
      local h = botster.crypto.sha256{ bytes_b64 = e.value }
      local m = botster.crypto.hmac_sha256{ key_b64 = e.value, bytes_b64 = e.value }
      local r = botster.crypto.random_bytes{ n = 8 }
      return { all_ok = e.ok and d.ok and j.ok and jd.ok and i.ok and now.ok and mono.ok and h.ok and m.ok and r.ok, returned = true }
    end }},
}
